"""Regression coverage for binary overrides, component builds and generated bytes."""

from __future__ import annotations

import json
import os
import shutil
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path
from unittest.mock import patch

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT))
from scripts.check_contracts import check_generated  # noqa: E402
from scripts.test_tools import binary_for  # noqa: E402
from scripts.sync_contracts import sync  # noqa: E402


class DevelopmentChecks(unittest.TestCase):
    def test_explicit_missing_binary_does_not_build(self) -> None:
        with tempfile.TemporaryDirectory(prefix="sledra-missing-tools-") as tmp:
            with patch.dict(os.environ, SLEDRA_TEST_BIN_DIR=tmp):
                with patch("scripts.test_tools.subprocess.run") as build:
                    with self.assertRaisesRegex(FileNotFoundError, "missing executable"):
                        binary_for("sledra", Path(tmp))
                    build.assert_not_called()

    def test_shared_binary_is_used_from_path_with_spaces(self) -> None:
        with tempfile.TemporaryDirectory(prefix="sledra tools ") as tmp:
            binary = Path(tmp) / "sledra"
            binary.write_text("#!/bin/sh\nexit 0\n")
            binary.chmod(0o700)
            with patch.dict(os.environ, SLEDRA_TEST_BIN_DIR=tmp):
                with patch("scripts.test_tools.subprocess.run") as build:
                    self.assertEqual(binary_for("sledra", Path(tmp)), binary)
                    build.assert_not_called()

    def test_generation_drift_is_detected_without_rewriting_source(self) -> None:
        with tempfile.TemporaryDirectory(prefix="sledra-generation-") as tmp:
            root = Path(tmp)
            for directory in (
                "spec",
                "recorder/event/contract",
                "recorder/internal/speccontract/contract",
            ):
                shutil.copytree(ROOT / directory, root / directory)
            shutil.copyfile(ROOT / "pyproject.toml", root / "pyproject.toml")
            schema = root / "spec/1.0.0/event.schema.json"
            schema.write_bytes(schema.read_bytes() + b" ")
            before = schema.read_bytes()
            with self.assertRaisesRegex(ValueError, "event.schema.json: generated bytes differ"):
                check_generated(root)
            self.assertEqual(schema.read_bytes(), before)

    def test_component_build_reuses_only_intact_binary(self) -> None:
        with tempfile.TemporaryDirectory(prefix="sledra build with spaces ") as tmp:
            command = [
                "make",
                "-C",
                str(ROOT / "recorder"),
                f"OUTPUT_DIR={tmp}",
                "TOOLS=sledra",
                "build",
            ]
            first = subprocess.run(command, capture_output=True, text=True, check=True)
            self.assertIn("Build ", first.stdout)
            binary = Path(tmp) / "bin/sledra"
            self.assertTrue(binary.is_file())
            second = subprocess.run(command, capture_output=True, text=True, check=True)
            self.assertIn("Reuse ", second.stdout)
            binary.write_bytes(b"damaged executable")
            binary.chmod(0o755)
            repaired = subprocess.run(command, capture_output=True, text=True, check=True)
            self.assertIn("Build ", repaired.stdout)
            self.assertNotEqual(binary.read_bytes(), b"damaged executable")
            manifest = json.loads((Path(tmp) / "manifest.json").read_text())
            self.assertEqual(manifest["recipe"]["tools"], ["sledra"])

    def test_embed_drift_is_detected_and_canonical_sync_restores_it(self) -> None:
        with tempfile.TemporaryDirectory(prefix="sledra-embed-drift-") as tmp:
            root = Path(tmp)
            for directory in (
                "spec",
                "recorder/event/contract",
                "recorder/internal/speccontract/contract",
            ):
                shutil.copytree(ROOT / directory, root / directory)
            shutil.copyfile(ROOT / "pyproject.toml", root / "pyproject.toml")
            embedded = root / "recorder/internal/speccontract/contract/run_context.schema.json"
            embedded.write_bytes(b"{}\n")
            with self.assertRaisesRegex(
                ValueError, "run_context.schema.json: differs from canonical"
            ):
                check_generated(root)
            self.assertEqual(embedded.read_bytes(), b"{}\n")
            sync(root)
            check_generated(root)


if __name__ == "__main__":
    unittest.main(verbosity=2)
